# syntax=docker/dockerfile:1
# Contexto: raiz do repositório (global.json e Directory.*.props ficam lá).
# A mesma imagem serve a API e o contêiner de migração (`migrate`).

FROM mcr.microsoft.com/dotnet/sdk:10.0 AS build
WORKDIR /src

# Restauração em camada própria: só refaz quando um .csproj ou .props muda.
COPY global.json Directory.Build.props Directory.Packages.props ./
COPY apps/api/src/Maxx.Domain/Maxx.Domain.csproj apps/api/src/Maxx.Domain/
COPY apps/api/src/Maxx.Application/Maxx.Application.csproj apps/api/src/Maxx.Application/
COPY apps/api/src/Maxx.Infrastructure/Maxx.Infrastructure.csproj apps/api/src/Maxx.Infrastructure/
COPY apps/api/src/Maxx.Api/Maxx.Api.csproj apps/api/src/Maxx.Api/
RUN dotnet restore apps/api/src/Maxx.Api/Maxx.Api.csproj

COPY .editorconfig ./
COPY apps/api/src/ apps/api/src/
RUN dotnet publish apps/api/src/Maxx.Api/Maxx.Api.csproj -c Release -o /app --no-restore

FROM mcr.microsoft.com/dotnet/aspnet:10.0 AS runtime
WORKDIR /app
COPY --from=build /app .
# Usuário sem privilégio que a imagem oficial já traz.
USER $APP_UID
EXPOSE 8080
ENTRYPOINT ["dotnet", "Maxx.Api.dll"]
using Maxx.Infrastructure.Persistence;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;

namespace Maxx.Api.IntegrationTests;

public sealed class MaxxApiFactory(string connectionString, string environment = "Development")
    : WebApplicationFactory<Program>
{
    // Porta 1 recusa conexão: banco fora do ar sem depender de contêiner.
    public const string UnreachableDatabase =
        "Host=127.0.0.1;Port=1;Database=maxx;Username=maxx;Password=maxx;Timeout=2";

    protected override void ConfigureWebHost(IWebHostBuilder builder) =>
        builder.UseSetting("ConnectionStrings:Maxx", connectionString).UseEnvironment(environment);

    // O mesmo caminho do subcomando migrate, num escopo próprio.
    public async Task MigrateAsync(CancellationToken cancellationToken)
    {
        await using var scope = Services.CreateAsyncScope();
        await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(cancellationToken);
    }
}
using System.Reflection;

namespace Maxx.Architecture.Tests;

// Api conhece Application. Application conhece Domain. Infrastructure implementa o que
// Application e Domain declaram. Domain não conhece ninguém. A Api também referencia a
// Infrastructure, mas só como raiz de composição (registro de dependências).
public class LayerDependencyTests
{
    [Fact]
    public void Domain_nao_depende_de_nenhum_projeto_Maxx()
    {
        Assert.Empty(MaxxReferencesOf("Maxx.Domain"));
    }

    [Fact]
    public void Domain_so_referencia_a_biblioteca_padrao()
    {
        var references = Assembly.Load(new AssemblyName("Maxx.Domain"))
            .GetReferencedAssemblies()
            .Select(reference => reference.Name!);

        Assert.All(references, name => Assert.True(
            name.StartsWith("System", StringComparison.Ordinal) || name == "netstandard",
            $"Maxx.Domain referencia {name}."));
    }

    [Fact]
    public void Application_depende_so_do_Domain()
    {
        Assert.Subset(new HashSet<string> { "Maxx.Domain" }, MaxxReferencesOf("Maxx.Application"));
    }

    [Fact]
    public void Infrastructure_nao_depende_da_Api()
    {
        Assert.Subset(
            new HashSet<string> { "Maxx.Domain", "Maxx.Application" },
            MaxxReferencesOf("Maxx.Infrastructure"));
    }

    private static HashSet<string> MaxxReferencesOf(string assemblyName) =>
        Assembly.Load(new AssemblyName(assemblyName))
            .GetReferencedAssemblies()
            .Select(reference => reference.Name!)
            .Where(name => name.StartsWith("Maxx.", StringComparison.Ordinal))
            .ToHashSet();
}

