        CadastroElegivel.Professor("bruno@prof.unieduk.com.br", "Bruno Lima");

    private static readonly CadastroElegivel ProfessorEInstituicao =
        CadastroElegivel.Professor("carla@unieduk.com.br", "Carla Dias", tambemInstituicao: true);

    private static readonly CadastroElegivel Instituicao =
        CadastroElegivel.Instituicao("secretaria@unieduk.com.br", "Secretaria UniMax");

    [Fact]
    public void Aluno_se_matricula_na_turma()
    {
        var matricula = new Matricula(Aluno, BancoDeDados2026);

        Assert.Equal(Aluno.Id, matricula.AlunoId);
        Assert.Equal(BancoDeDados2026.Id, matricula.TurmaId);
    }

    [Fact]
    public void Professor_nao_se_matricula()
    {
        Assert.Throws<DomainException>(() => new Matricula(Professor, BancoDeDados2026));
    }

    [Fact]
    public void Instituicao_nao_se_matricula()
    {
        Assert.Throws<DomainException>(() => new Matricula(Instituicao, BancoDeDados2026));
    }

    [Fact]
    public void Professor_se_vincula_a_turma()
    {
        var vinculo = new VinculoProfessor(Professor, BancoDeDados2026);

        Assert.Equal(Professor.Id, vinculo.ProfessorId);
        Assert.Equal(BancoDeDados2026.Id, vinculo.TurmaId);
    }

    [Fact]
    public void Professor_que_tambem_e_instituicao_se_vincula_a_turma()
