        Assert.Equal(ProfessorEInstituicao.Id, vinculo.ProfessorId);
    }

    [Fact]
    public void Aluno_nao_se_vincula_como_professor()
    {
        Assert.Throws<DomainException>(() => new VinculoProfessor(Aluno, BancoDeDados2026));
    }

    [Fact]
    public void Instituicao_sem_professor_nao_se_vincula()
    {
        Assert.Throws<DomainException>(() => new VinculoProfessor(Instituicao, BancoDeDados2026));
    }
}

