                return AlvoDeConquista.De(fixo);
            case { ValueKind: JsonValueKind.String } texto
                when texto.GetString() == Camel(nameof(AlvoDeConquista.TodasAsMatriculasDoPeriodo)):
                return AlvoDeConquista.TodasAsMatriculasDoPeriodo;
