        builder.HasIndex(ano => ano.Ano).IsUnique();

        builder.HasMany(ano => ano.Semestres)
            .WithOne()
            .HasForeignKey("AnoLetivoId")
            .IsRequired()
            .OnDelete(DeleteBehavior.Cascade);
        builder.Navigation(ano => ano.Semestres).HasField("_semestres");

