                ["ra"] = "20260206",
                ["email"] = "outro.aluno@al.unieduk.com.br",
                ["nomeCompleto"] = "Outro Aluno",
                ["semestre"] = 1,
                ["materias"] = new JsonArray("Marketing"),
            });
        });
        var falha = await Assert.ThrowsAsync<SeedException>(() => factory.SeedDemoAsync(Ct));

        Assert.Contains("ana.souza@al.unieduk.com.br", falha.Message, StringComparison.Ordinal);
        Assert.Equal(antes, await ContagensAsync(factory));
    }

    [Fact]
    public async Task Semestre_do_aluno_alem_da_duracao_do_curso_falha()
    {
        await using var factory = await ComBaseAsync();

        _copia.Alterar("demo/mundo.json", mundo => Alunos(mundo, "CC")[0]!["semestre"] = 9);
        var falha = await Assert.ThrowsAsync<SeedException>(() => factory.SeedDemoAsync(Ct));

        Assert.Contains("ana.souza@al.unieduk.com.br", falha.Message, StringComparison.Ordinal);
        Assert.Equal((0, 0, 0, 0, 0), await ContagensAsync(factory));
    }

    [Fact]
    public async Task Materia_citada_que_nao_existe_no_curso_falha()
    {
        await using var factory = await ComBaseAsync();

        // Aluno de Administração em Algoritmos: a matéria é de CC.
        _copia.Alterar("demo/mundo.json", mundo => Alunos(mundo, "ADM")[0]!["materias"] = new JsonArray("Algoritmos e Programação"));
        var falha = await Assert.ThrowsAsync<SeedException>(() => factory.SeedDemoAsync(Ct));

        Assert.Contains("Algoritmos e Programação", falha.Message, StringComparison.Ordinal);
        Assert.Equal((0, 0, 0, 0, 0), await ContagensAsync(factory));
    }

    [Fact]
    public async Task Email_repetido_no_arquivo_falha()
    {
        await using var factory = await ComBaseAsync();

        _copia.Alterar("demo/mundo.json", mundo => Alunos(mundo, "MED")[0]!["email"] = "ANA.SOUZA@al.unieduk.com.br");
        var falha = await Assert.ThrowsAsync<SeedException>(() => factory.SeedDemoAsync(Ct));

        Assert.Contains("e-mail repetido", falha.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task Turma_em_semestre_fora_do_calendario_falha()
    {
        await using var factory = await ComBaseAsync();

        _copia.Alterar("demo/mundo.json", mundo => Curso(mundo, "MED")["materias"]![0]!["turmas"] = new JsonArray("2027/1"));
        var falha = await Assert.ThrowsAsync<SeedException>(() => factory.SeedDemoAsync(Ct));

        Assert.Contains("2027/1", falha.Message, StringComparison.Ordinal);
        Assert.Equal((0, 0, 0, 0, 0), await ContagensAsync(factory));
    }

    [Fact]
    public async Task Restricao_de_curso_para_sigla_existente_passa()
    {
        _copia.AlterarItem("premios-participacao.json", "P05", item => item["restricaoCurso"] = "MED");
        await using var factory = await ComBaseAsync();

        await factory.SeedDemoAsync(Ct);
    }

    [Fact]
    public async Task Restricao_de_curso_para_sigla_inexistente_falha_sem_gravar_nada()
    {
        _copia.AlterarItem("premios-participacao.json", "P05", item => item["restricaoCurso"] = "ENG");
        await using var factory = await ComBaseAsync();

        var falha = await Assert.ThrowsAsync<SeedException>(() => factory.SeedDemoAsync(Ct));

        Assert.Contains("P05 (ENG)", falha.Message, StringComparison.Ordinal);
        Assert.Equal((0, 0, 0, 0, 0), await ContagensAsync(factory));
    }

    private async Task<MaxxApiFactory> ComBaseAsync()
    {
        var factory = await MigradoAsync(postgres, _copia.Diretorio);
        await factory.SeedBaseAsync(Ct);
        return factory;
    }

    private static JsonObject Curso(JsonNode mundo, string sigla) =>
        mundo["cursos"]!.AsArray().Single(curso => (string?)curso!["sigla"] == sigla)!.AsObject();

    private static JsonArray Alunos(JsonNode mundo, string sigla) => Curso(mundo, sigla)["alunos"]!.AsArray();

    private static async Task<(int Cursos, int Turmas, int Cadastros, int Matriculas, int Vinculos)> ContagensAsync(
        MaxxApiFactory factory)
    {
        await using var scope = factory.Services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<MaxxDbContext>();
        return (
            await db.Set<Curso>().CountAsync(Ct),
            await db.Set<Turma>().CountAsync(Ct),
            await db.Set<CadastroElegivel>().CountAsync(Ct),
            await db.Set<Matricula>().CountAsync(Ct),
            await db.Set<VinculoProfessor>().CountAsync(Ct));
    }
}

content.text:
A E6 está no commit `4823185`, já enviado.

A E7 está pronta para sua revisão e ainda sem commit. Os 205 testes passam, contando 15 novos do demo, e o build, o `dotnet format` e o Prettier estão limpos.

**Comprovado no Compose:** subi com o banco zerado, e o `seed base` rodou sozinho.
- O primeiro `docker compose run --rm seeder seed demo` gravou 3 cursos, 12 matérias, 12 turmas, 19 cadastros, 60 matrículas e 12 vínculos.
- O segundo não gravou nada.
- No banco, cada curso ficou com 4 turmas, 5 alunos e 1 professor.

**O que entrou**
- **`data/demo/mundo.json`**, com o que você definiu:
  - CC, ADM e MED, com 8, 8 e 12 semestres, e as 4 matérias de cada um;
  - uma turma por matéria em 2026/2;
  - um professor por curso, vinculado às 4 turmas do curso;
  - cinco alunos por curso, em semestres variados (até o 12º em MED) e matriculados nas 4 turmas;
  - uma conta de instituição.

  Nomes, RAs e e-mails são fictícios; a `observacao` do arquivo diz isso.
- **O `MundoDemoReader`** confere a coerência do arquivo: sigla, e-mail (sem diferenciar maiúsculas) e RA únicos, e matérias citadas existindo no curso. Todo o resto é validado pelo domínio, quando o seeder constrói cada objeto.
- **O `SeedDemoAsync`**, no mesmo lock e numa transação só.
  - Exige o base e explica isso se ele não rodou.
  - Acrescenta o que falta, pela chave natural de cada coisa: sigla, (curso, nome), (matéria, semestre), e-mail e os pares de matrícula e de vínculo.
  - Conferência que você pediu: toda `restricao_curso` do catálogo precisa apontar para uma sigla existente. Senão o seed falha sem gravar nada, com uma mensagem como `P05 (ENG)`.
- **O seeder foi dividido em `SeedBaseAsync` e `SeedDemoAsync`**, cada um com seu resultado. A cópia temporária de `data/` usada pelos testes foi para `CopiaDeDados`, compartilhada com os testes da E6.

**Os testes cobrem**
- as contagens e as durações dos cursos;
- toda turma com professor e todo aluno com matrícula em 2026/2;
- nenhum aluno em turma de outro curso;
- rodar de novo sem mudar nada, e o base continuar idempotente depois do demo;
- o demo sem o base falhar com explicação;
- uma linha de fora do arquivo ficar no banco, e um aluno novo no arquivo entrar sem mexer no resto;
- recusas, cada uma sem gravar nada:
  - cadastro que diverge do arquivo, junto com outra mudança válida da mesma rodada;
  - semestre do aluno além da duração do curso;
  - aluno de ADM citando Algoritmos;
  - e-mail repetido com outra caixa;
  - turma em 2027/1, que não está no calendário;
  - `restricao_curso` válida e inválida.

**Escolhas minhas (confirme ou peça ajuste)**
1. **O mundo é arquivo de dados**, como o calendário, e não código. É ele que cresce até os 150 alunos do passo 12.
2. **O demo só acrescenta e não falha por linha a mais.** É diferente do base de propósito: os alunos que a banca criar no passo 5 vão morar nessas tabelas sem estar no arquivo, e um seed que falhasse por eles quebraria na hora da apresentação.
3. **Uma linha que existe nos dois lugares e diverge faz o seed falhar, em vez de ser corrigida.** O domínio não tem operação de correção de cadastro, e corrigir é ato da instituição, que chega no passo 12.
4. **Professor e aluno listam as matérias e entram em todas as turmas delas**; cada matéria lista os semestres em que tem turma. Assim dá para acrescentar turmas de 2026/1 depois sem mudar o formato do arquivo.
5. **Os dados fictícios:**
   - RAs de 8 dígitos (`2026CCNN`);
   - e-mails `nome.sobrenome` nos três domínios de `produto.md`;
   - a conta de instituição é `coordenacao@unieduk.com.br`, com o nome "Coordenação UniMax";
   - os professores são Renata Albuquerque (CC), Marcos Teixeira (ADM) e Helena Duarte (MED).

   O formato do RA não está nos docs. Se a UniMax usa outro, troco no arquivo.

**Commit proposto:** `feat(seed): adiciona perfil demo do seeder`

Com a E7 aprovada, o passo fecha. Faço o commit e o push, e abro o PR de `feat/passo-02-dados` para `rodada/eng_02_dados` com os sete commits. Na descrição do PR não entra rodapé de co-autoria nem menção a ferramenta, como pede o CLAUDE.md.

